INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6dc-7545-99f7-60cd11ca51f2'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Factorise completely: 6y^2 - 15y.', '3y(2y - 5)', 'Take out the common factor 3y. This gives 6y^2 - 15y = 3y(2y - 5).', 'Easy', '{"tags":"algebra,factorisation,common-factor","subtopic":"factorisation","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.884Z'::timestamptz, '2026-07-26T12:42:25.884Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6de-78c6-bd8c-d34069e07a12'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Factorise completely: x^2 - 9x + 20.', '(x - 4)(x - 5)', 'Find two numbers whose product is 20 and sum is -9. They are -4 and -5, so the expression factorises to (x - 4)(x - 5).', 'Easy', '{"tags":"algebra,factorisation,quadratics","subtopic":"quadratic factorisation","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.886Z'::timestamptz, '2026-07-26T12:42:25.886Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6e0-7e2c-84ee-9587e00dc897'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'y is directly proportional to the cube root of (x + 1). It is given that x = 7 when y = 1. Find the value of y when x = 124.', '2.5', 'Let y = k∛(x + 1). When x = 7, 1 = k∛8 = 2k, so k = 1/2. When x = 124, y = 1/2 × ∛125 = 1/2 × 5 = 2.5.', 'Medium', '{"tags":"ratio,direct-proportion,cube-root","subtopic":"direct proportion","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.888Z'::timestamptz, '2026-07-26T12:42:25.888Z'::timestamptz) ON CONFLICT (id) DO NOTHING;